#!/usr/bin/env python3
"""Customize the Android directory generated by `flutter create --platforms=android .`."""
from pathlib import Path
import re

root = Path(__file__).resolve().parents[1]
android = root / 'android'
gradle = android / 'app' / 'build.gradle.kts'
if not gradle.exists():
    raise SystemExit('Android scaffold missing: run flutter create --platforms=android --org=com.luminaplan .')

s = gradle.read_text()
s = re.sub(r'compileSdk\s*=\s*flutter\.compileSdkVersion', 'compileSdk = 36', s)
s = re.sub(r'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 24', s)
s = re.sub(r'targetSdk\s*=\s*flutter\.targetSdkVersion', 'targetSdk = 35', s)
if 'multiDexEnabled' not in s:
    s = re.sub(r'defaultConfig\s*\{', 'defaultConfig {\n        multiDexEnabled = true', s, count=1)
if 'isCoreLibraryDesugaringEnabled' not in s:
    s = re.sub(r'compileOptions\s*\{', 'compileOptions {\n        isCoreLibraryDesugaringEnabled = true', s, count=1)
if 'coreLibraryDesugaring(' not in s:
    s += '\n\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
if 'sourceCompatibility = JavaVersion.VERSION_17' not in s:
    s = re.sub(r'sourceCompatibility\s*=\s*JavaVersion\.VERSION_\d+', 'sourceCompatibility = JavaVersion.VERSION_17', s)
if 'targetCompatibility = JavaVersion.VERSION_17' not in s:
    s = re.sub(r'targetCompatibility\s*=\s*JavaVersion\.VERSION_\d+', 'targetCompatibility = JavaVersion.VERSION_17', s)
s = re.sub(r'jvmTarget\s*=\s*JavaVersion\.VERSION_\d+\.toString\(\)', 'jvmTarget = JavaVersion.VERSION_17.toString()', s)
gradle.write_text(s)

settings = android / 'settings.gradle.kts'
if settings.exists():
    s = settings.read_text()
    s, count = re.subn(r'(id\("com\.android\.application"\) version ")[^"]+(" apply false)', r'\g<1>8.11.1\2', s)
    if count != 1:
        raise SystemExit('Could not set AGP version in android/settings.gradle.kts')
    settings.write_text(s)

wrapper = android / 'gradle' / 'wrapper' / 'gradle-wrapper.properties'
if wrapper.exists():
    s = wrapper.read_text()
    s = re.sub(r'(distributionUrl=https\\://services.gradle.org/distributions/gradle-)[^\s]+(-(?:all|bin)\.zip)', r'\g<1>8.14.3\2', s)
    wrapper.write_text(s)

manifest = android / 'app' / 'src' / 'main' / 'AndroidManifest.xml'
manifest.write_text('''<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />
    <uses-permission android:name="android.permission.VIBRATE" />
    <application android:label="LuminaPlan"
        android:name="${applicationName}"
        android:icon="@mipmap/ic_launcher">
        <activity android:name=".MainActivity"
            android:exported="true"
            android:launchMode="singleTop"
            android:taskAffinity=""
            android:theme="@style/LaunchTheme"
            android:configChanges="orientation|keyboardHidden|keyboard|screenSize|smallestScreenSize|locale|layoutDirection|fontScale|screenLayout|density|uiMode"
            android:hardwareAccelerated="true"
            android:windowSoftInputMode="adjustResize">
            <meta-data android:name="io.flutter.embedding.android.NormalTheme"
                android:resource="@style/NormalTheme" />
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>
        <meta-data android:name="flutterEmbedding" android:value="2" />
        <receiver android:exported="false"
            android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />
        <receiver android:exported="false"
            android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED" />
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED" />
                <action android:name="android.intent.action.QUICKBOOT_POWERON" />
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON" />
            </intent-filter>
        </receiver>
    </application>
    <queries>
        <intent>
            <action android:name="android.intent.action.PROCESS_TEXT" />
            <data android:mimeType="text/plain" />
        </intent>
    </queries>
</manifest>
''')

sizes = {'mipmap-mdpi': 48, 'mipmap-hdpi': 72, 'mipmap-xhdpi': 96,
         'mipmap-xxhdpi': 144, 'mipmap-xxxhdpi': 192}
for dirname, size in sizes.items():
    src = root / 'assets' / 'branding' / 'owl_app.png'
    dst = android / 'app' / 'src' / 'main' / 'res' / dirname / 'ic_launcher.png'
    if src.exists():
        dst.parent.mkdir(parents=True, exist_ok=True)
        dst.write_bytes(src.read_bytes())

print('Android: notificações locais, Gradle, desugaring e ícone configurados.')
